import pandas as pd

def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep=False)
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'].str.replace(',', '', regex=False), errors='coerce')
    df = df[(df['body_mass_g'].between(2500, 6500)) & (df['body_mass_g'].notna())]
    df['island'] = df['island'].str.strip()
    return df

def answer(df):
    grouped = df.groupby('island')['penguin_id'].count()
    return {name: count for name, count in grouped.items()}
